begin

  ----------------------------------------------------------------------------
  -- Step sequencer (replaces the on-chip two-phase clock generator)
  --   step 0  G1  PRECH            step 3  G2  -
  --   step 1  S2  CLK, PRECH       step 4  S0  CLKN
  --   step 2  S3  CLK, T10MHZ      step 5  S1  CLKN, T10MHZ
  ----------------------------------------------------------------------------
  step_next <= (others => '0') when step_reg = 5 else step_reg + 1;

  PRECH    <= '1' when step_reg = 0 or step_reg = 1 else '0';
  CLK_PH   <= '1' when step_reg = 1 or step_reg = 2 else '0';
  T10MHZ   <= '1' when step_reg = 2 or step_reg = 5 else '0';
  CLKN_PH  <= '1' when step_reg = 4 or step_reg = 5 else '0';

  ----------------------------------------------------------------------------
  -- Pins
  ----------------------------------------------------------------------------
  A0       <= pin_a(0);
  A1       <= pin_a(1);
  CLOCK    <= '0';
  CSN      <= pin_csn;
  OEN      <= pin_oen;
  RDN      <= pin_rdn;
  RESETN   <= pin_resetn;
  TEST     <= pin_test;
  WRN      <= pin_wrn;
  drive_ALE <= X177159_X5K0 or X177159_X6K0;   -- chip drives the pad
  drive_BOUTCSYNC <= X141597_X5K0 or X141597_X6K0;   -- chip drives the pad
  drive_OUTSTBNT1 <= X111596_X5K0 or X111596_X6K0;   -- chip drives the pad
  drive_V0T0 <= X71599_X5K0 or X71599_X6K0;   -- chip drives the pad
  drive_DB0 <= X111143_X5K0 or X111143_X6K0;   -- chip drives the pad
  pin_db_out(0) <= DB0;
  pin_db_oe(0)  <= drive_DB0;
  drive_DB1 <= X110142_X5K0 or X110142_X6K0;   -- chip drives the pad
  pin_db_out(1) <= DB1;
  pin_db_oe(1)  <= drive_DB1;
  drive_DB2 <= X109141_X5K0 or X109141_X6K0;   -- chip drives the pad
  pin_db_out(2) <= DB2;
  pin_db_oe(2)  <= drive_DB2;
  drive_DB3 <= X108140_X5K0 or X108140_X6K0;   -- chip drives the pad
  pin_db_out(3) <= DB3;
  pin_db_oe(3)  <= drive_DB3;
  drive_DB4 <= X107139_X5K0 or X107139_X6K0;   -- chip drives the pad
  pin_db_out(4) <= DB4;
  pin_db_oe(4)  <= drive_DB4;
  drive_DB5 <= X106138_X5K0 or X106138_X6K0;   -- chip drives the pad
  pin_db_out(5) <= DB5;
  pin_db_oe(5)  <= drive_DB5;
  drive_DB6 <= X8182_X5K0 or X8182_X6K0;   -- chip drives the pad
  pin_db_out(6) <= DB6;
  pin_db_oe(6)  <= drive_DB6;
  drive_DB7 <= X105137_X5K0 or X105137_X6K0;   -- chip drives the pad
  pin_db_out(7) <= DB7;
  pin_db_oe(7)  <= drive_DB7;

  ----------------------------------------------------------------------------
  -- Logic gates
  ----------------------------------------------------------------------------
  ACC0B <= not (X388K1 or LDSAMP);
  ACC10B <= not (X452K1 or LDSAMP);
  ACC11B <= not (X459K1 or LDSAMP);
  ACC12B <= not (X466K1 or LDSAMP);
